package io.github.diodeme.ji.hcp;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.google.protobuf.ByteString;
import io.github.diodeme.ji.hcp.v1.Command;
import io.github.diodeme.ji.hcp.v1.Envelope;
import io.github.diodeme.ji.hcp.v1.ErrorDetail;
import org.junit.jupiter.api.Test;

final class HcpContractTest {
    @Test
    void commandEnvelopeRoundTripsWithRevisionIdentity() throws Exception {
        var envelope = Envelope.newBuilder()
                .setProtocolVersion(1)
                .setConnectionId("connection-1")
                .setCommand(Command.newBuilder()
                        .setCommandId("command-1")
                        .setSessionId("session-1")
                        .setExpectedRevision(7)
                        .setPayload(ByteString.copyFromUtf8("payload")))
                .build();

        var parsed = Envelope.parseFrom(envelope.toByteArray());
        assertEquals(Envelope.PayloadCase.COMMAND, parsed.getPayloadCase());
        assertEquals(7, parsed.getCommand().getExpectedRevision());
        assertEquals("command-1", parsed.getCommand().getCommandId());
    }

    @Test
    void structuredErrorPreservesOptionalRecoveryFields() throws Exception {
        var envelope = Envelope.newBuilder()
                .setProtocolVersion(1)
                .setConnectionId("connection-1")
                .setError(ErrorDetail.newBuilder()
                        .setCode("queue.revision_conflict")
                        .putParameters("expectedRevision", "6")
                        .setTraceId("trace-1")
                        .setRetryAfterMillis(250)
                        .setCurrentRevision(7))
                .build();

        var parsed = Envelope.parseFrom(envelope.toByteArray()).getError();
        assertTrue(parsed.hasTraceId());
        assertTrue(parsed.hasRetryAfterMillis());
        assertTrue(parsed.hasCurrentRevision());
        assertEquals(7, parsed.getCurrentRevision());
    }
}
